import { Linking, ScrollView, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { ProfileSection, TeamsSection } from './components'
import { router } from 'expo-router'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import * as WebBrowser from 'expo-web-browser'
import { HeaderBar, SettingsItem, SettingsSectionTitle } from '@/components'
import { useCurrentOrganization } from '@/utils/hooks'
import Purchases from 'react-native-purchases'
import { useEffect, useState } from 'react'
import { OrganizationPlan } from '@/generated/graphql'
import {
	purchaseCreditsEmitter,
	PurchaseCreditsEvents,
	upgradePlanEmitter,
	UpgradePlanEvents
} from '@/utils/emitter'
import { useBoolVariation } from '@launchdarkly/react-native-client-sdk'
import { useLogout } from '@/utils/hooks/useLogout'
import { CreditUsage } from './components/CreditUsage'

export type Organization = {
	id: string
	name: string
	logoUrl: string | null
}

type ProfileScreenProps = {
	displayName: string | null
	email: string
	profileImage: string | null
	organizations: Organization[]
	blurhash: string
}

export const ProfileScreen = ({
	displayName,
	email,
	profileImage,
	organizations,
	blurhash
}: ProfileScreenProps) => {
	const insets = useSafeAreaInsets()
	const { theme } = useTheme()
	const { handleLogout } = useLogout()
	const deleteAccountEnabled = useBoolVariation('delete-account-enabled', false)
	const creditUsageVisibleEnabled = useBoolVariation(
		'credit-usage-visible-enabled',
		false
	)

	const { currentOrganization } = useCurrentOrganization()
	const [appUserId, setAppUserId] = useState<string | null>(null)

	useEffect(() => {
		Purchases.getAppUserID().then(setAppUserId)
	}, [])

	const isFreePlan =
		currentOrganization &&
		(currentOrganization.plan === OrganizationPlan.FREE_USAGE ||
			currentOrganization?.plan === OrganizationPlan.FREE)

	const isSubscribed =
		appUserId &&
		currentOrganization &&
		currentOrganization.revenueCatUserId === appUserId

	return (
		<>
			<ScrollView
				style={styles.scrollView(theme)}
				showsVerticalScrollIndicator={false}
				contentContainerStyle={{
					paddingTop: insets.top,
					paddingBottom: insets.bottom + 16,
					paddingHorizontal: 24
				}}
			>
				<HeaderBar
					title="Profile"
					onClose={() => {
						router.back()
					}}
				/>
				<View style={styles.settingsItemsContainer}>
					<ProfileSection
						profileImage={profileImage ? { uri: profileImage } : null}
						name={displayName ?? email}
						email={email}
						blurhash={blurhash}
					/>
				</View>

				{creditUsageVisibleEnabled && (
					<View style={styles.settingsItemsContainer}>
						<CreditUsage
							plan={currentOrganization?.plan ?? OrganizationPlan.FREE_USAGE}
							balance={BigInt(currentOrganization?.creditBalance ?? 0n)}
							planCredits={BigInt(currentOrganization?.planCredits ?? 0n)}
							subscriptionStartDate={
								currentOrganization?.subscriptionStartDate ?? null
							}
							canUseMax={currentOrganization?.canUseMax ?? false}
						/>
					</View>
				)}

				<View style={styles.settingsItemsContainer}>
					<TeamsSection teams={organizations} />
				</View>

				<View style={styles.settingsItemsContainer}>
					<SettingsSectionTitle title="Subscription & Credits" />

					{isFreePlan && (
						<SettingsItem
							title="Upgrade plan"
							onPress={() =>
								upgradePlanEmitter.emit(UpgradePlanEvents.OPEN_MODAL)
							}
							type="button"
						/>
					)}

					{isSubscribed && (
						<SettingsItem
							title="Manage subscription"
							onPress={() =>
								Linking.openURL('https://apps.apple.com/account/subscriptions')
							}
							type="button"
						/>
					)}

					<SettingsItem
						title="Purchase credits"
						onPress={() =>
							purchaseCreditsEmitter.emit(PurchaseCreditsEvents.OPEN_MODAL)
						}
						type="button"
					/>
				</View>
				<View style={styles.settingsItemsContainer}>
					<SettingsSectionTitle title="Support" />
					<SettingsItem
						title="Help"
						onPress={() =>
							WebBrowser.openBrowserAsync(
								'https://www.createanything.com/docs/welcome'
							)
						}
						type="link"
					/>

					<SettingsItem
						title="Blog"
						onPress={() =>
							WebBrowser.openBrowserAsync('https://www.createanything.com/blog')
						}
						type="link"
					/>
					<SettingsItem
						title="Privacy"
						onPress={() =>
							WebBrowser.openBrowserAsync(
								'https://www.createanything.com/privacy-policy'
							)
						}
						type="link"
					/>
					<SettingsItem
						title="Terms of Service"
						onPress={() =>
							WebBrowser.openBrowserAsync('https://www.createanything.com/tos')
						}
						type="link"
					/>
				</View>
				<View style={styles.settingsItemsContainer}>
					<SettingsSectionTitle title="Account" />
					<SettingsItem title="Log out" onPress={handleLogout} type="none" />
					{deleteAccountEnabled && (
						<SettingsItem
							title="Delete account"
							onPress={() => router.push('/profile/delete-account')}
							type="button"
							appearance="destructive"
						/>
					)}
				</View>
			</ScrollView>
		</>
	)
}

const styles = defineStyles({
	scrollView: (theme: Theme) => ({
		backgroundColor: colors[theme].background
	}),
	section: {
		gap: 0
	},
	settingsItemsContainer: {
		gap: 4,
		marginTop: 40
	}
})
